const cfg=window.AFRIRISE_CONFIG,form=document.querySelector('#support-form'),btn=document.querySelector('#support-submit');if(cfg.apiBase){btn.disabled=false;btn.textContent='Send request ↗';document.querySelector('#support-notice').textContent='Your request will be sent to AfriRise for staff review. Cancellation is confirmed separately.'}form.addEventListener('submit',async e=>{e.preventDefault();if(!cfg.apiBase)return;btn.disabled=true;try{const r=await fetch(cfg.apiBase+'/request',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind:document.querySelector('#kind').value,email:document.querySelector('#email').value,message:document.querySelector('#message').value,website:document.querySelector('#website').value})});const result=await r.json();if(!r.ok)throw new Error(result.error);document.querySelector('#support-feedback').textContent=result.message;form.reset()}catch(e){document.querySelector('#support-feedback').textContent=e.message}finally{btn.disabled=false}});
